tool_input.command:
node -e "
const { parse } = require('./src/parse.js');

// Test basic date parsing
const tests = [
  { input: '2024-01-15', description: 'ISO date' },
  { input: '2024-01-15T10:30:00Z', description: 'ISO datetime with Z' },
  { input: 'Mon Jan 15 2024', description: 'US date format' },
  { input: 'January 15, 2024', description: 'Full date format' },
];

let passed = 0;
let failed = 0;

tests.forEach(test => {
  try {
    const result = parse(test.input);
    if (result instanceof Date && !isNaN(result.getTime())) {
      console.log('✓ PASS:', test.description, '->', result.toISOString());
      passed++;
    } else {
      console.log('✗ FAIL:', test.description, '- result is not a valid Date');
      failed++;
    }
  } catch (e) {
    console.log('✗ FAIL:', test.description, '-', e.message);
    failed++;
  }
});

console.log(\`\nSummary: \${passed} passed, \${failed} failed\`);
process.exit(failed > 0 ? 1 : 0);
"

node << 'EOF'
const { parse } = require('./src/parse.js');

console.log('Testing date parser...');

// Test 1: ISO date string
const d1 = parse('2024-01-15');
console.log('ISO date:', d1 instanceof Date && !isNaN(d1) ? '✓ PASS' : '✗ FAIL');

// Test 2: ISO datetime with Z
const d2 = parse('2024-01-15T10:30:00Z');
console.log('ISO datetime:', d2 instanceof Date && !isNaN(d2) ? '✓ PASS' : '✗ FAIL');

// Test 3: Full date format  
const d3 = parse('January 15, 2024');
console.log('Full format:', d3 instanceof Date && !isNaN(d3) ? '✓ PASS' : '✗ FAIL');

// Test 4: Invalid date
const d4 = parse('invalid');
console.log('Invalid input:', d4 instanceof Date ? '✓ PASS (returns Date object)' : '✗ FAIL');
console.log('  - IsNaN:', isNaN(d4) ? 'true (as expected for invalid)' : 'false');
EOF
